(3710256, 522290, 1024, '<td valign="top">I do not see where this photo fits the challenge description.  Yes I see her hair blowing a tiny little bit, but this is more of a portrait of a beautiful girl that was squeezed into the wrong challenge.</td>', 'I do not see where this photo fits the challenge description.  Yes I see her hair blowing a tiny little bit, but this is more of a portrait of a beautiful girl that was squeezed into the wrong challenge.', '2007-05-29 19:41:22.000000', NULL, 1),
(3710341, 521897, 76198, '<td valign="top">Processing is overdone, for my tastes, and the sky seems weird - like it''s upside down almost, though this is advanced editing so I assume it just happened to look that way. Nice color in the sky.</td>', 'Processing is overdone, for my tastes, and the sky seems weird - like it''s upside down almost, though this is advanced editing so I assume it just happened to look that way. Nice color in the sky.', '2007-05-29 20:11:15.000000', NULL, 1),
