(3719298, 522048, 39181, '<td valign="top">Love everything about thos one  ..10</td>', 'Love everything about thos one  ..10', '2007-05-31 13:44:07.000000', NULL, 1),
(3719369, 521871, 76198, '<td valign="top">The most refreshing element is gin?<br/> <br/>Nice photo. Lemon is maybe a wee bit bright, could be more yellow and a little darker.</td>', 'The most refreshing element is gin? Nice photo. Lemon is maybe a wee bit bright, could be more yellow and a little darker.', '2007-05-31 14:19:20.000000', NULL, 1),
(3719375, 521628, 76198, '<td valign="top">This is the stuff I love; simple, moody, evocative. Perfect composition, love the bokeh, love the color and texture of the water. <br/> <br/>Unfortunately these shots don''t tend to do well here; I truly hope yours is an exception. I''ll give it a 9.</td>', 'This is the stuff I love; simple, moody, evocative. Perfect composition, love the bokeh, love the color and texture of the water.  Unfortunately these shots don''t tend to do well here; I truly hope yours is an exception. I''ll give it a 9.', '2007-05-31 14:21:52.000000', NULL, 1),
(3719379, 522211, 76198, '<td valign="top">This would be much more effective if it didn''t look like it was noon when it was taken; even dusk would have been better. Your candle flame doesn''t take center stage - in fact I have to look for it, and then it seems out of place.</td>', 'This would be much more effective if it didn''t look like it was noon when it was taken; even dusk would have been better. Your candle flame doesn''t take center stage - in fact I have to look for it, and then it seems out of place.', '2007-05-31 14:24:32.000000', NULL, 1),
(3719386, 521948, 76198, '<td valign="top">Cool. Very pretty. Nice color.<br/> <br/>Would be much improved if the window were cleaner. - the dried water spots are distracting.</td>', 'Cool. Very pretty. Nice color. Would be much improved if the window were cleaner. - the dried water spots are distracting.', '2007-05-31 14:25:55.000000', NULL, 1),
(3719390, 521491, 76198, '<td valign="top">Very cool - I would have liked it more in it''s natural orientation.</td>', 'Very cool - I would have liked it more in it''s natural orientation.', '2007-05-31 14:27:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3719394, 521829, 76198, '<td valign="top">Umm... Awesome? 9.<br/> <br/>Colors are perfect, and I love the composition; how she looks like she''s about to float out of the picture. Would have been a 10 from me except for what appear to be blown highlights in the upper arm (or at least it is, to my mind, overbright there). <br/> <br/>The floating sheet is amazing.</td>', 'Umm... Awesome? 9. Colors are perfect, and I love the composition; how she looks like she''s about to float out of the picture. Would have been a 10 from me except for what appear to be blown highlights in the upper arm (or at least it is, to my mind, overbright there).  The floating sheet is amazing.', '2007-05-31 14:30:07.000000', NULL, 1),
(3719402, 520816, 76198, '<td valign="top">So cute! A baby. Very different that the others. Texture on the main drip is also exceptionally nice.</td>', 'So cute! A baby. Very different that the others. Texture on the main drip is also exceptionally nice.', '2007-05-31 14:31:26.000000', NULL, 1),
(3719407, 521546, 76198, '<td valign="top">Improved? In what way? <br/> <br/>Blown highlights in the hand are distracting, but the eyes are great; particularly the one on my right. great DOF.</td>', 'Improved? In what way?  Blown highlights in the hand are distracting, but the eyes are great; particularly the one on my right. great DOF.', '2007-05-31 14:32:58.000000', NULL, 1),
(3719411, 521788, 76198, '<td valign="top">This is, I''m afraid, not terribly appealing to me - it''s a bit bright, and the greens of the seaweed are a touch offputting. <br/> <br/>Would have come out better near sundown, I think...</td>', 'This is, I''m afraid, not terribly appealing to me - it''s a bit bright, and the greens of the seaweed are a touch offputting.  Would have come out better near sundown, I think...', '2007-05-31 14:34:56.000000', NULL, 1),
(3719422, 519237, 76198, '<td valign="top">I was getting burnt out on waterfall pics, but this is perfect. Really great. Looks like you blurred the background a bit? Nice touch</td>', 'I was getting burnt out on waterfall pics, but this is perfect. Really great. Looks like you blurred the background a bit? Nice touch', '2007-05-31 14:36:39.000000', NULL, 1),
(3719431, 521576, 76198, '<td valign="top">Love the composition, and choice of subject; the sunset view is nice, I feel like a little more light on the boat would help it though.</td>', 'Love the composition, and choice of subject; the sunset view is nice, I feel like a little more light on the boat would help it though.', '2007-05-31 14:37:59.000000', NULL, 1),
(3719434, 521363, 76198, '<td valign="top">Best of these so far. 9.</td>', 'Best of these so far. 9.', '2007-05-31 14:38:57.000000', NULL, 1),
(3719813, 521996, 42100, '<td valign="top">Unique and intriguing colors...I like the abstract approach to the subjects.  Very nice photo!</td>', 'Unique and intriguing colors...I like the abstract approach to the subjects.  Very nice photo!', '2007-05-31 16:14:17.000000', NULL, 1),
(3719820, 521766, 42100, '<td valign="top">Very pretty water lilies...they really pop against the darker tones of the water.  Beautiful photograph!</td>', 'Very pretty water lilies...they really pop against the darker tones of the water.  Beautiful photograph!', '2007-05-31 16:15:23.000000', NULL, 1),
(3719835, 521715, 42100, '<td valign="top">The black and orange make a wonderful color combination.  The "part-way-in the-frame" composition works really well, especially with the vivid color combo.</td>', 'The black and orange make a wonderful color combination.  The "part-way-in the-frame" composition works really well, especially with the vivid color combo.', '2007-05-31 16:18:53.000000', NULL, 1),
(3719837, 521502, 42100, '<td valign="top">The silhouettes are well defined and look great against that dramatic sky.  Very nice photo!</td>', 'The silhouettes are well defined and look great against that dramatic sky.  Very nice photo!', '2007-05-31 16:20:01.000000', NULL, 1),
(3719841, 522285, 42100, '<td valign="top">Strong and dynamic contrast, and the tones assist nicely in focusing the attention towards the areas of interest.  Well done!</td>', 'Strong and dynamic contrast, and the tones assist nicely in focusing the attention towards the areas of interest.  Well done!', '2007-05-31 16:21:51.000000', NULL, 1),
(3719848, 520474, 42100, '<td valign="top">No coincidence I guess that hot and cold subjects are also the hot &amp; cold tones...very interesting how the two tones blend from the two sides via the water droplets and reflections.  Nicely done!</td>', 'No coincidence I guess that hot and cold subjects are also the hot & cold tones...very interesting how the two tones blend from the two sides via the water droplets and reflections.  Nicely done!', '2007-05-31 16:25:16.000000', NULL, 1),
(3719851, 521727, 42100, '<td valign="top">Very nice design with the placement of the sun.  Very nice tones and texture to the formation.  Great job!</td>', 'Very nice design with the placement of the sun.  Very nice tones and texture to the formation.  Great job!', '2007-05-31 16:26:38.000000', NULL, 1),
(3719856, 520815, 42100, '<td valign="top">The tones are much more intriguing than the actual water drop in this photo...some very nice texture to this as well.  Well done!</td>', 'The tones are much more intriguing than the actual water drop in this photo...some very nice texture to this as well.  Well done!', '2007-05-31 16:28:11.000000', NULL, 1),
(3719862, 522231, 42100, '<td valign="top">Very nice light on the new plant, it really emphasises the texture nicely.  Good high-quality close-up!</td>', 'Very nice light on the new plant, it really emphasises the texture nicely.  Good high-quality close-up!', '2007-05-31 16:30:06.000000', NULL, 1),
(3719864, 521256, 42100, '<td valign="top">Those little droplets really catch your eye against those deep dark tones of the leaves and background.  Very nice photograph!</td>', 'Those little droplets really catch your eye against those deep dark tones of the leaves and background.  Very nice photograph!', '2007-05-31 16:30:27.000000', NULL, 1),
(3719868, 521991, 20330, '<td valign="top">I''d like to see a deeper more colorful green on the main leaf.. and the thin border is not present on the bottom and right side of the image (unless something is wrong with my monitor).. but a good attempt at a widely used subject.</td>', 'I''d like to see a deeper more colorful green on the main leaf.. and the thin border is not present on the bottom and right side of the image (unless something is wrong with my monitor).. but a good attempt at a widely used subject.', '2007-05-31 16:32:11.000000', NULL, 1),
(3719869, 521559, 42100, '<td valign="top">Beautiful setting...the orange of the sail really pops against the more graysih tones of the background.  Great photo and looks like a very interesting place!</td>', 'Beautiful setting...the orange of the sail really pops against the more graysih tones of the background.  Great photo and looks like a very interesting place!', '2007-05-31 16:32:26.000000', NULL, 1),
