(3724445, 521454, 63812, '<td valign="top">peaceful and pretty</td>', 'peaceful and pretty', '2007-06-01 14:58:37.000000', NULL, 1),
(3724457, 522249, 42100, '<td valign="top">Very unique and beautiful composition, and the tones and colors are exquisite.  Outstanding photograph!</td>', 'Very unique and beautiful composition, and the tones and colors are exquisite.  Outstanding photograph!', '2007-06-01 15:01:14.000000', NULL, 1),
(3724459, 520373, 63812, '<td valign="top">the contrast is too strong</td>', 'the contrast is too strong', '2007-06-01 15:02:04.000000', NULL, 1),
(3724460, 521821, 63812, '<td valign="top">good</td>', 'good', '2007-06-01 15:02:32.000000', NULL, 1),
(3724461, 521733, 42100, '<td valign="top">Great color and clarity to this photo.  Those out of focus droplets looks like shining little gems.  Very nice!</td>', 'Great color and clarity to this photo.  Those out of focus droplets looks like shining little gems.  Very nice!', '2007-06-01 15:02:32.000000', NULL, 1),
(3724463, 521502, 63812, '<td valign="top">very nice. You''re right...peaceful and relaxing</td>', 'very nice. You''re right...peaceful and relaxing', '2007-06-01 15:04:02.000000', NULL, 1),
(3724467, 522148, 42100, '<td valign="top">The combination of colors really give this photo some serious zing.  The favorable lighting really weakens as you get towards the bonsai.  The greens in the tree lack the zing.  Still very much an excellent photo!</td>', 'The combination of colors really give this photo some serious zing.  The favorable lighting really weakens as you get towards the bonsai.  The greens in the tree lack the zing.  Still very much an excellent photo!', '2007-06-01 15:05:26.000000', NULL, 1),
(3724468, 522298, 42100, '<td valign="top">Great whimsy to this photo, the light and tones are just perfect.  Very nicely done!</td>', 'Great whimsy to this photo, the light and tones are just perfect.  Very nicely done!', '2007-06-01 15:05:43.000000', NULL, 1),
(3724475, 522209, 42100, '<td valign="top">Very pleasing and peaceful scene.  The composing and DOF really keeps this from becoming a photo that is much too busy.  Beautifully done!</td>', 'Very pleasing and peaceful scene.  The composing and DOF really keeps this from becoming a photo that is much too busy.  Beautifully done!', '2007-06-01 15:07:56.000000', NULL, 1),
(3724479, 519578, 56828, '<td valign="top">Out of focus.  Your background is too cluttered (more blurred background would help).  The right side of the rose is overexposed as well.  Could also use some color pop.</td>', 'Out of focus.  Your background is too cluttered (more blurred background would help).  The right side of the rose is overexposed as well.  Could also use some color pop.', '2007-06-01 15:08:35.000000', NULL, 1),
