(3729218, 522276, 70270, '<td valign="top">I''ve seen Rock City ... interesting place.  Lots of opportunities to get closer to your subject or really go for some detail shots.  This one looks too much like a quick travel snapshot that lacks any special interest.  Difficult to make a good photo from this vantage, with the strong light above and the waterfall in shadows.  4</td>', 'I''ve seen Rock City ... interesting place.  Lots of opportunities to get closer to your subject or really go for some detail shots.  This one looks too much like a quick travel snapshot that lacks any special interest.  Difficult to make a good photo from this vantage, with the strong light above and the waterfall in shadows.  4', '2007-06-02 15:28:16.000000', NULL, 1),
(3729220, 521660, 55621, '<td valign="top">Which element was he?</td>', 'Which element was he?', '2007-06-02 15:28:54.000000', NULL, 1),
(3729221, 522252, 70270, '<td valign="top">Meets the challenge, but just doesn''t have a lot of visual interest for me.  A 4 on my first run through, but a 5 is more realistic.</td>', 'Meets the challenge, but just doesn''t have a lot of visual interest for me.  A 4 on my first run through, but a 5 is more realistic.', '2007-06-02 15:29:12.000000', NULL, 1),
(3729223, 522206, 55621, '<td valign="top">This just doesn''t jump out at me.</td>', 'This just doesn''t jump out at me.', '2007-06-02 15:29:37.000000', NULL, 1),
(3729226, 522145, 55621, '<td valign="top">There is too much negative on the bottom, distracts from the waterfall.</td>', 'There is too much negative on the bottom, distracts from the waterfall.', '2007-06-02 15:30:41.000000', NULL, 1),
(3729227, 521525, 70270, '<td valign="top">Nice try, but not as sharp or interesting as some of the real wow shots in this category.  Check out IreneM''s profile to see how she carries off images like this.  They are tough to do -- and this one shows how difficult it can be to get it right.  4.</td>', 'Nice try, but not as sharp or interesting as some of the real wow shots in this category.  Check out IreneM''s profile to see how she carries off images like this.  They are tough to do -- and this one shows how difficult it can be to get it right.  4.', '2007-06-02 15:31:01.000000', NULL, 1),
(3729229, 522124, 55621, '<td valign="top">The darkening sky needs a little more punch, causes the whole image to be flat.</td>', 'The darkening sky needs a little more punch, causes the whole image to be flat.', '2007-06-02 15:31:40.000000', NULL, 1),
(3729233, 521243, 55621, '<td valign="top">At what age do you harvest the children?  Clever idea. 8</td>', 'At what age do you harvest the children?  Clever idea. 8', '2007-06-02 15:32:39.000000', NULL, 1),
(3729234, 521777, 70270, '<td valign="top">Lighting is too dark, and the set up is uninteresting.  The exposure on the flames is very nice, however.  If you would have come in really tight on the candle tops and not tried to capture the silver candelabras this would havee been nicer.  As it is, have to give you a 4.</td>', 'Lighting is too dark, and the set up is uninteresting.  The exposure on the flames is very nice, however.  If you would have come in really tight on the candle tops and not tried to capture the silver candelabras this would havee been nicer.  As it is, have to give you a 4.', '2007-06-02 15:32:44.000000', NULL, 1),
(3729238, 522155, 70270, '<td valign="top">Nice blur on the windmill, but don''t care for the composition ... the tree next to the mill takes too much attention away from your subject.  4.</td>', 'Nice blur on the windmill, but don''t care for the composition ... the tree next to the mill takes too much attention away from your subject.  4.', '2007-06-02 15:33:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3729239, 522315, 70270, '<td valign="top">Nice scene, but a little washed out.  Maybe bumping the saturation and contrast would help.  5.</td>', 'Nice scene, but a little washed out.  Maybe bumping the saturation and contrast would help.  5.', '2007-06-02 15:34:25.000000', NULL, 1),
(3729241, 520372, 55621, '<td valign="top">Converting this into IR, you seem to have lost some of the elements, the contrasts between the color of the water and the trees in the background.</td>', 'Converting this into IR, you seem to have lost some of the elements, the contrasts between the color of the water and the trees in the background.', '2007-06-02 15:34:54.000000', NULL, 1),
(3729245, 521976, 55621, '<td valign="top">A little tighter crop off the top and this could have been a ribbon. 8</td>', 'A little tighter crop off the top and this could have been a ribbon. 8', '2007-06-02 15:35:55.000000', NULL, 1),
(3729287, 519850, 55621, '<td valign="top">Beautiful photograph.</td>', 'Beautiful photograph.', '2007-06-02 15:51:57.000000', NULL, 1),
(3729300, 520579, 55621, '<td valign="top">This is a wonderful image.  The contrast of the whites and grays is a perfect blend. 9</td>', 'This is a wonderful image.  The contrast of the whites and grays is a perfect blend. 9', '2007-06-02 15:54:55.000000', NULL, 1),
(3729303, 521821, 43410, '<td valign="top">this is amazing.  i really love this</td>', 'this is amazing.  i really love this', '2007-06-02 15:55:38.000000', NULL, 1),
(3729309, 519593, 55621, '<td valign="top">At first it seemed too dark but if you were to lighten it the reflects would fade. The reds could have been a little more prominent.</td>', 'At first it seemed too dark but if you were to lighten it the reflects would fade. The reds could have been a little more prominent.', '2007-06-02 15:57:23.000000', NULL, 1),
(3729312, 522375, 55621, '<td valign="top">Where''s Jack, oh the number 24, my mistake...</td>', 'Where''s Jack, oh the number 24, my mistake...', '2007-06-02 15:58:48.000000', NULL, 1),
(3729318, 519908, 55621, '<td valign="top">Too much distraction in the top right corner.</td>', 'Too much distraction in the top right corner.', '2007-06-02 15:59:40.000000', NULL, 1),
(3729335, 522122, 55621, '<td valign="top">Looks like you have some lens vignetting in the top corners.</td>', 'Looks like you have some lens vignetting in the top corners.', '2007-06-02 16:05:23.000000', NULL, 1),
(3729341, 522179, 55621, '<td valign="top">The bottom half of your image is too dark, you lost a lot of detail in your image.</td>', 'The bottom half of your image is too dark, you lost a lot of detail in your image.', '2007-06-02 16:06:34.000000', NULL, 1),
(3729344, 522174, 55621, '<td valign="top">This is very nice, would look great as a larger image.</td>', 'This is very nice, would look great as a larger image.', '2007-06-02 16:07:44.000000', NULL, 1),
(3729345, 521948, 55621, '<td valign="top">Not enough detail in the water drops.</td>', 'Not enough detail in the water drops.', '2007-06-02 16:08:21.000000', NULL, 1),
(3729350, 522033, 55621, '<td valign="top">Reoccurring theme in this challenge, nicely done.</td>', 'Reoccurring theme in this challenge, nicely done.', '2007-06-02 16:08:56.000000', NULL, 1),
(3729412, 521783, 43156, '<td valign="top">This is a really lucky shot. Good capture.</td>', 'This is a really lucky shot. Good capture.', '2007-06-02 16:49:09.000000', NULL, 1),
(3729790, 521485, 5354, '<td valign="top">Tremendous use and control of light. Well worth a ribbon in my opinion.</td>', 'Tremendous use and control of light. Well worth a ribbon in my opinion.', '2007-06-02 19:04:33.000000', NULL, 1),
(3729960, 520459, 76454, '<td valign="top">+</td>', '+', '2007-06-02 20:30:50.000000', NULL, 1),
(3729973, 522013, 69493, '<td valign="top">8</td>', '8', '2007-06-02 20:36:04.000000', NULL, 1),
(3730021, 521708, 70270, '<td valign="top">Sorry, this is just too busy.  For a good shot of moving water, you need to use a tripod so you can shoot at a very slow shutter speed, blurring the water and conveying the sense of movement.  I don''t think this particular image is suited to a stop action (fast) shutter speed.</td>', 'Sorry, this is just too busy.  For a good shot of moving water, you need to use a tripod so you can shoot at a very slow shutter speed, blurring the water and conveying the sense of movement.  I don''t think this particular image is suited to a stop action (fast) shutter speed.', '2007-06-02 20:53:35.000000', NULL, 1),
(3730024, 522034, 70270, '<td valign="top">It is a reflection, and so a nice idea, but the image itself ... both the building and tis reflection, just isn''t that interesting.</td>', 'It is a reflection, and so a nice idea, but the image itself ... both the building and tis reflection, just isn''t that interesting.', '2007-06-02 20:54:34.000000', NULL, 1),
(3730026, 521172, 70270, '<td valign="top">The colors seem too unnatural, and there''s not a lot of visual interest in the composition.</td>', 'The colors seem too unnatural, and there''s not a lot of visual interest in the composition.', '2007-06-02 20:55:33.000000', NULL, 1),
(3730029, 521995, 70270, '<td valign="top">Good idea for a subject, but the reflection of the pole across the flag and the trees in the background ruin this one for me.  I like the backwards flying flag  .</td>', 'Good idea for a subject, but the reflection of the pole across the flag and the trees in the background ruin this one for me.  I like the backwards flying flag  .', '2007-06-02 20:56:40.000000', NULL, 1),
(3730032, 522172, 70270, '<td valign="top">The composition kills this one.  There''s no central point of interest in the frame.  True dirt is earth and one of the elements, but that alone is not enough to hold my interest</td>', 'The composition kills this one.  There''s no central point of interest in the frame.  True dirt is earth and one of the elements, but that alone is not enough to hold my interest', '2007-06-02 20:57:59.000000', NULL, 1),
(3730034, 521760, 70270, '<td valign="top">Good sharpness, and nice color contrast between the rim of the planter and the background, but the dirt and the seed are not a very attractive subject.</td>', 'Good sharpness, and nice color contrast between the rim of the planter and the background, but the dirt and the seed are not a very attractive subject.', '2007-06-02 20:58:57.000000', NULL, 1),
(3730037, 522233, 70270, '<td valign="top">Not really meeting the challenge that well here, and the attempt at cheescake would have been better if your subject didn''t have her hand in front of her face, and her knee wasn''t cut out of the frame on the right.  Shooting down at an angle hurt this one too ... try shooting straight across or at just a slight angle up towards the model next time ... the background would have been much better if the camera was lower when you took this shot.</td>', 'Not really meeting the challenge that well here, and the attempt at cheescake would have been better if your subject didn''t have her hand in front of her face, and her knee wasn''t cut out of the frame on the right.  Shooting down at an angle hurt this one too ... try shooting straight across or at just a slight angle up towards the model next time ... the background would have been much better if the camera was lower when you took this shot.', '2007-06-02 21:01:32.000000', NULL, 1),
(3730042, 521967, 70270, '<td valign="top">Nothing interesting to look at here, and a poor choice of subject.  I''d like to give you some constructive comment, but I can''t think of anything to suggest that would improve this.</td>', 'Nothing interesting to look at here, and a poor choice of subject.  I''d like to give you some constructive comment, but I can''t think of anything to suggest that would improve this.', '2007-06-02 21:03:00.000000', NULL, 1),
(3730153, 522182, 55621, '<td valign="top">The would have been a 10 in my book had it not been for the branches on the lower left. Beautiful photo 8</td>', 'The would have been a 10 in my book had it not been for the branches on the lower left. Beautiful photo 8', '2007-06-02 21:41:28.000000', NULL, 1),
(3730339, 521634, 38477, '<td valign="top">Nice concept, but a little bit of more light on her face (flash?) would have made this better.</td>', 'Nice concept, but a little bit of more light on her face (flash?) would have made this better.', '2007-06-02 23:05:11.000000', NULL, 1),
(3730463, 521794, 10426, '<td valign="top">asda</td>', 'asda', '2007-06-02 23:58:28.000000', NULL, 1),
