(3731901, 521985, 56502, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2007-06-03 12:49:55.000000', NULL, 1),
(3731974, 522230, 1031, '<td valign="top">Good positioning to contrast the whitewater with the dark foliage, splash of bright color right in the middle -- nice action shot.</td>', 'Good positioning to contrast the whitewater with the dark foliage, splash of bright color right in the middle -- nice action shot.', '2007-06-03 13:07:48.000000', NULL, 1),
